34|export type AutoFormFieldConfig = {
35|  field: ApiFormField;
36|  /** When false the field is skipped entirely (no control, no binding). */
37|  enabled: boolean;
38|  /** User-editable display label. */
39|  label: string;
40|  /** Chosen control palette item id (may differ from the suggested default). */
41|  controlPaletteItemId: string;
42|};
