44|export type AutoFormLayout = 'single' | 'two-column';
45|
46|export type AutoFormBuildConfig = {
47|  /** Optional heading rendered above the form fields. */
48|  title?: string;
49|  includeTitle: boolean;
50|  dataSource: DataSourceDefinition;
51|  scenario: FormBindingScenario;
52|  fields: AutoFormFieldConfig[];
53|  submitLabel: string;
