68|const MODAL_PALETTE_ITEM_IDS = new Set(['heroui.modal', 'heroui.alert-dialog']);
69|
70|const AUTO_FORM_LAYOUT_CONTAINER_IDS = new Set([
71|  'layout.flex-column',
72|  'html.container',
73|]);
