75|const resolveNodePaletteItemId = (node: DesignerNode): string | undefined => {
76|  const stored = node.props[DESIGNER_PALETTE_ITEM_ID_PROP];
77|  return typeof stored === 'string' && stored.trim().length > 0 ? stored.trim() : undefined;
78|};
79|
80|const findFormRegionUnder = (document: DesignerDocument, parentId: string): DesignerNode | null => {
81|  for (const childId of document.nodes[parentId]?.children ?? []) {
82|    const child = document.nodes[childId];
83|    if (child && resolveNodePaletteItemId(child) === 'html.form' && isDataRegionEligibleContainer(child)) {
84|      return child;
85|    }
86|  }
87|
88|  return null;
89|};
90|
91|const collectSubtreeNodeIds = (document: DesignerDocument, rootId: string): string[] => {
92|  const ids: string[] = [];
93|  const queue = [rootId];
94|
95|  while (queue.length > 0) {
96|    const id = queue.shift();
97|    if (!id) {
98|      continue;
99|    }
100|
101|    const node = document.nodes[id];
102|    if (!node) {
103|      continue;
104|    }
105|
106|    ids.push(id);
107|    queue.push(...node.children);
108|  }
109|
110|  return ids;
111|};
