113|const removeNodesFromDocument = (
114|  document: DesignerDocument,
115|  nodeIds: readonly string[],
116|): DesignerDocument['nodes'] => {
117|  const nextNodes = { ...document.nodes };
118|  for (const nodeId of nodeIds) {
119|    delete nextNodes[nodeId];
120|  }
121|  return nextNodes;
