124|const mergeDataSourceIntoBindings = (
125|  bindingDefinitions: DesignerBindingDefinitions,
126|  dataSource: DataSourceDefinition,
127|): DesignerBindingDefinitions => ({
128|  ...bindingDefinitions,
129|  dataSources: {
130|    ...bindingDefinitions.dataSources,
131|    [dataSource.id]: dataSource,
132|  },
