135|const buildBaseInfoLovsForFields = (fields: AutoFormFieldConfig[]): Record<string, LovDefinition> => {
136|  const lovs: Record<string, LovDefinition> = {};
137|
138|  for (const entry of fields) {
139|    if (!entry.enabled) {
140|      continue;
141|    }
142|
143|    const rootId = resolveBaseInfoRootForField(entry.field.name);
144|    if (!rootId) {
145|      continue;
146|    }
147|
148|    const lovId = lovIdForBaseInfoField(entry.field.name);
149|    lovs[lovId] = {
150|      id: lovId,
151|      name: humanizeFieldName(entry.field.name),
152|      endpoint: buildBaseInfoOptionsEndpoint(rootId),
153|      displayValue: 'label',
154|      returnValue: 'id',
155|    };
156|  }
157|
158|  return lovs;
159|};
