161|const mergeAutoFormBindings = (
162|  bindingDefinitions: DesignerBindingDefinitions,
163|  config: AutoFormBuildConfig,
164|): DesignerBindingDefinitions => {
165|  const baseInfoLovs = buildBaseInfoLovsForFields(config.fields);
166|
167|  return {
168|    ...mergeDataSourceIntoBindings(bindingDefinitions, config.dataSource),
169|    lovs: {
170|      ...bindingDefinitions.lovs,
171|      ...baseInfoLovs,
172|    },
173|  };
