176|/** True when the canvas root already has designed content (not a blank starter). */
177|export const documentHasDesignedContent = (document: DesignerDocument): boolean => {
178|  const root = document.nodes[document.rootNodeId];
179|  return (root?.children?.length ?? 0) > 0;
