182|/**
183| * Resolves where an auto-generated form should be inserted based on the current selection.
184| * Returns null when the selection does not point at a form region or modal shell.
185| */
186|export const resolveAutoFormInsertTarget = (
187|  document: DesignerDocument,
188|  selectedNodeId: string | null,
189|): AutoFormInsertTarget | null => {
190|  if (!selectedNodeId) {
191|    return null;
192|  }
193|
194|  const selected = document.nodes[selectedNodeId];
195|  if (!selected) {
196|    return null;
197|  }
198|
199|  const paletteItemId = resolveNodePaletteItemId(selected);
200|
201|  if (paletteItemId === 'html.form' && isDataRegionEligibleContainer(selected)) {
202|    return { mode: 'form-region', formNodeId: selected.id };
203|  }
204|
205|  if (paletteItemId && MODAL_PALETTE_ITEM_IDS.has(paletteItemId)) {
206|    const existingForm = findFormRegionUnder(document, selected.id);
207|    if (existingForm) {
208|      return { mode: 'form-region', formNodeId: existingForm.id };
209|    }
210|
211|    return { mode: 'modal-insert', modalNodeId: selected.id };
212|  }
213|
214|  if (paletteItemId && AUTO_FORM_LAYOUT_CONTAINER_IDS.has(paletteItemId)) {
215|    const existingForm = findFormRegionUnder(document, selected.id);
216|    if (existingForm) {
217|      return { mode: 'form-region', formNodeId: existingForm.id };
218|    }
219|  }
